    @Transactional(rollbackFor = Exception.class)
    public void createOrder(Order order) throws Exception {
        orderRepository.save(order);
        deductStock(order);
    }

    private void deductStock(Order order) {
        // 扣库存：这个方法不是 public，上面的注解对它无效
    }
}

