import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface UserRepository extends JpaRepository<User, Long> {

    // 默认 JPQL：写实体名和属性名，不是表名
    @Query("select u from User u where u.status = :status")
    List<User> findByStatus(@Param("status") String status);

    // 原生 SQL 必须显式声明 nativeQuery = true
    @Query(value = "select * from t_user where age > :age", nativeQuery = true)
    List<User> findOlderThan(@Param("age") int age);
}

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.transaction.annotation.Transactional;

public interface UserRepository extends JpaRepository<User, Long> {

    // 更新语句必须加 @Modifying，并且要在事务里调用
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Transactional
    @Query("update User u set u.status = :status where u.id = :id")
    int updateStatus(@Param("id") Long id, @Param("status") String status);

    // 删除也是修改型查询，同样要 @Modifying
    @Modifying
    @Transactional
    @Query("delete from User u where u.id = :id")
    int deleteById(@Param("id") Long id);
}

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface OrderRepository extends JpaRepository<Order, Long> {

    // 一个参数在 JPQL 里用两次，必须用 @Param 起名才能复用
    @Query("select o from Order o where o.buyer = :username or o.seller = :username")
    List<Order> findByEitherSide(@Param("username") String username);

    // 多个参数时每个都要起名，名字和 :buyer、:status 对应
    @Query("select o from Order o where o.buyer = :buyer and o.status = :status")
    List<Order> findByBuyerAndStatus(@Param("buyer") String buyer,
                                     @Param("status") String status);
}

import javax.sql.DataSource;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.orm.jpa.JpaTransactionManager;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;
import org.springframework.transaction.PlatformTransactionManager;

@Configuration
@EnableJpaRepositories(
    basePackages = "com.example.order.repository",
    entityManagerFactoryRef = "orderEntityManagerFactory",
    transactionManagerRef = "orderTransactionManager"
)
public class OrderDataConfig {

    @Bean
    public LocalContainerEntityManagerFactoryBean orderEntityManagerFactory(DataSource dataSource) {
        LocalContainerEntityManagerFactoryBean emf = new LocalContainerEntityManagerFactoryBean();
        emf.setDataSource(dataSource);
        emf.setPackagesToScan("com.example.order.entity");
        emf.setJpaVendorAdapter(new HibernateJpaVendorAdapter());
        return emf;
    }

    @Bean
    public PlatformTransactionManager orderTransactionManager(
            LocalContainerEntityManagerFactoryBean orderEntityManagerFactory) {
        return new JpaTransactionManager(orderEntityManagerFactory.getObject());
    }
}

import java.util.List;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Select;

// Boot 的 mybatis starter 会自动扫描 @Mapper 接口
@Mapper
public interface UserMapper {

    @Select("select id, username from t_user where id = #{id}")
    User findById(Long id);

    @Select("select id, username from t_user")
    List<User> findAll();

    @Select("select count(*) from t_user")
    long count();
}

import org.mybatis.spring.annotation.MapperScan;
import org.springframework.context.annotation.Configuration;

// 扫描包下所有接口，批量注册成 MyBatis 代理 Bean
@Configuration
@MapperScan(
    basePackages = "com.example.mapper",
    sqlSessionFactoryRef = "sqlSessionFactory"
)
public class MyBatisConfig {

    // 多数据源时，每套 SqlSessionFactory 配一个 @MapperScan
    // 单数据源项目可以不写这个类，让 starter 扫描 @Mapper 即可
    // 每个 Mapper 接口注册成 bean 后，名字默认是接口名首字母小写
    // 需要更细的扫描范围时，再加 annotationClass 或 markerInterface 过滤
}

import java.util.List;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

@Mapper
public interface BookMapper {

    // 多个字符串会用空格拼成一条 SQL，方便拆行
    @Select({
        "select id, title, author",
        "from t_book",
        "where title like concat('%', #{keyword}, '%')"
    })
    List<Book> search(@Param("keyword") String keyword);
}

import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Options;

@Mapper
public interface UserMapper {

    // 自增主键要靠 @Options 才能回填到对象的 id 上
    @Insert("insert into t_user(username, email) values(#{username}, #{email})")
    @Options(useGeneratedKeys = true, keyProperty = "id")
    int insert(User user);

    // 返回值是影响行数，不是主键
    @Insert("insert into t_user(username) values(#{username})")
    int insertSimple(String username);
}

import java.time.LocalDateTime;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Update;

@Mapper
public interface UserMapper {

    // 返回影响行数：0 表示没有这个 id，或者值本来就没变
    @Update("update t_user set email = #{email}, updated_at = #{now} where id = #{id}")
    int updateEmail(@Param("id") Long id,
                    @Param("email") String email,
                    @Param("now") LocalDateTime now);

    @Update("update t_user set status = #{status} where id = #{id}")
    int updateStatus(@Param("id") Long id, @Param("status") String status);
}

import org.apache.ibatis.annotations.Delete;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;

@Mapper
public interface OrderMapper {

    // 物理删除，返回影响行数
    @Delete("delete from t_order where id = #{id}")
    int deleteById(@Param("id") Long id);

    @Delete("delete from t_order where user_id = #{userId} and status = #{status}")
    int deleteByUserAndStatus(@Param("userId") Long userId,
                              @Param("status") String status);
}

import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

@Mapper
public interface OrderMapper {

    // 多个参数必须用 @Param 起名，否则 SQL 里只能写 #{param1}、#{param2}
    @Select("select * from t_order where user_id = #{userId} and status = #{status}")
    java.util.List<Order> findByUserAndStatus(@Param("userId") Long userId,
                                              @Param("status") String status);

    // 只有一个参数时命名不强制
    @Select("select * from t_order where id = #{id}")
    Order findById(Long id);
}

import java.util.List;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Result;
import org.apache.ibatis.annotations.ResultMap;
import org.apache.ibatis.annotations.Results;
import org.apache.ibatis.annotations.Select;

@Mapper
public interface UserMapper {

    // 列名 user_name 和属性名 userName 对不上时，手写映射
    @Results(id = "userMap", value = {
        @Result(column = "id", property = "id", id = true),
        @Result(column = "user_name", property = "userName"),
        @Result(column = "created_at", property = "createdAt")
    })
    @Select("select id, user_name, created_at from t_user where id = #{id}")
    User findById(Long id);

    // 复用上面定义的映射集
    @ResultMap("userMap")
    @Select("select id, user_name, created_at from t_user")
    List<User> findAll();
}

import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.cache.concurrent.ConcurrentMapCacheManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@EnableCaching
public class CacheConfig {

    // 真实项目多换成 RedisCacheManager；没有 CacheManager 启动会报错
    @Bean
    public CacheManager cacheManager() {
        return new ConcurrentMapCacheManager("users", "orders");
    }
}

import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

@Service
public class UserService {

    private final UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    // 先查 users 缓存，没命中才执行方法并写入
    @Cacheable(cacheNames = "users", key = "#id", unless = "#result == null")
    public User getById(Long id) {
        return userRepository.findById(id).orElse(null);
    }
}

import org.springframework.cache.annotation.CachePut;
import org.springframework.stereotype.Service;

@Service
public class UserService {

    private final UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    // 方法一定执行，返回的 User 会写入 users 缓存
    @CachePut(cacheNames = "users", key = "#user.id")
    public User update(User user) {
        return userRepository.save(user);
    }
}

import org.springframework.cache.annotation.CacheEvict;
import org.springframework.stereotype.Service;

@Service
public class UserService {

    private final UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    // 删除后清掉对应 key
    @CacheEvict(cacheNames = "users", key = "#id")
    public void deleteById(Long id) {
        userRepository.deleteById(id);
    }

    // 列表缓存没法精确定位 key，直接清空整个 cache
    @CacheEvict(cacheNames = "userList", allEntries = true)
    public void refreshList() {
    }
}

import org.springframework.cache.annotation.CacheConfig;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

@Service
@CacheConfig(cacheNames = "users")
public class UserService {

    private final UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    // 不用再重复写 cacheNames = "users"
    @Cacheable(key = "#id")
    public User getById(Long id) {
        return userRepository.findById(id).orElse(null);
    }

    @CacheEvict(key = "#id")
    public void deleteById(Long id) {
        userRepository.deleteById(id);
    }
}

import java.util.concurrent.Executor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@Configuration
@EnableAsync
public class AsyncConfig {

    // 不配就用 Boot 默认的 applicationTaskExecutor
    @Bean("mailExecutor")
    public Executor mailExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(4);
        executor.setMaxPoolSize(8);
        executor.setQueueCapacity(200);
        executor.setThreadNamePrefix("mail-");
        executor.initialize();
        return executor;
    }
}

import java.util.concurrent.CompletableFuture;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;

@Service
public class MailService {

    // 从别的 Bean 调用才会走代理、进线程池
    @Async("mailExecutor")
    public void sendWelcome(String email) {
        System.out.println("send to " + email);
    }

    @Async
    public CompletableFuture<String> sendAsync(String email) {
        // 返回值只能是 void、Future 或 CompletableFuture
        return CompletableFuture.completedFuture("ok");
    }
}

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

@Configuration
@EnableScheduling
public class SchedulingConfig {

    // 默认调度器是单线程，多个任务会互相排队
    @Bean
    public ThreadPoolTaskScheduler taskScheduler() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(4);
        scheduler.setThreadNamePrefix("sched-");
        scheduler.initialize();
        return scheduler;
    }
}

import java.time.LocalDateTime;
