        System.out.println("build report at " + LocalDateTime.now());
    }

    // 上次执行完 30 秒后再跑，串行不会重叠
    @Scheduled(fixedDelay = 30_000)
    public void refreshCache() {
        // 刷新逻辑
    }
}
